THOUGHT: I’ll implement a compact shared-SQLite Python service with three HTTP node processes, a supervised IRC listener, authentication, workspace/channel/message/role/invitation APIs, a basic SPA, and durable per-channel events. The shared database gives stable cross-node state and event sequencing without external dependencies.

```mswea_bash_command
cat > /app/app.py <<'PY'
import os,sys,json,re,sqlite3,secrets,hashlib,base64,datetime,threading,time,socket,struct
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
DB='/app/huddle.db'; PORT=int(os.getenv('PORT','8000')); NODE=PORT-8000
db_lock=threading.RLock(); clients=[]

def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def conn():
 c=sqlite3.connect(DB,check_same_thread=False); c.row_factory=sqlite3.Row; return c
def init():
 with db_lock:
  c=conn()
  c.executescript('''PRAGMA journal_mode=WAL;
  CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
  CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
  CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
  CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
  CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0);
  CREATE TABLE IF NOT EXISTS cmembers(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
  CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
  CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
  CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,kind TEXT,payload TEXT,created_at TEXT,PRIMARY KEY(channel_id,event_id));
  CREATE TABLE IF NOT EXISTS pins(message_id INTEGER PRIMARY KEY,user_id INTEGER,pinned_at TEXT);
  CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY,workspace_id INTEGER,invited_user_id INTEGER,uses INTEGER DEFAULT 0,max_uses INTEGER DEFAULT 1);
  CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,user_ids TEXT);
  '''); c.commit(); c.close()
def user(r):
 return {'id':r['id'],'username':r['username'],'display_name':r['display_name'],'timezone':r['timezone'],'avatar_url':r['avatar_url'],'status_text':r['status_text'],'status_emoji':r['status_emoji']}
def auth(h):
 x=h.get('Authorization','')
 if not x.startswith('Bearer '): return None
 c=conn(); r=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(x[7:],)).fetchone(); c.close(); return r
def js(h,s=200): h.send_response(s); h.send_header('Content-Type','application/json'); h.end_headers(); h.wfile.write(json.dumps(h._out).encode())
def msgobj(c,r):
 a=c.execute('SELECT * FROM users WHERE id=?',(r['author_id'],)).fetchone()
 rx=[]
 for x in c.execute('SELECT emoji,COUNT(*) n FROM reactions WHERE message_id=? GROUP BY emoji',(r['id'],)):
  ids=[z[0] for z in c.execute('SELECT user_id FROM reactions WHERE message_id=? AND emoji=?',(r['id'],x['emoji']))]
  rx.append({'emoji':x['emoji'],'count':x['n'],'user_ids':ids})
 replies=c.execute('SELECT COUNT(*) FROM messages WHERE parent_id=? AND deleted=0',(r['id'],)).fetchone()[0]
 return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':user(a),'body':r['body'],'parent_id':r['parent_id'],'reply_count':replies,'created_at':r['created_at'],'edited_at':r['edited_at'],'files':[],'reactions':rx,'mentions':[]}
def emit(c,cid,kind,payload):
 n=c.execute('SELECT COALESCE(MAX(event_id),0)+1 FROM events WHERE channel_id=?',(cid,)).fetchone()[0]
 c.execute('INSERT INTO events VALUES(?,?,?,?,?)',(cid,n,kind,json.dumps(payload),now())); c.commit()
 frame={'type':kind,'event_id':n,'channel_id':cid}; frame.update(payload)
 for q in list(clients):
  try:
   if q[0]==cid: ws_send(q[1],frame)
  except: pass
 return n
def ws_send(s,x):
 b=json.dumps(x).encode(); s.sendall(b'\x81'+(bytes([len(b)]) if len(b)<126 else b'\x7e'+struct.pack('>H',len(b)))+b)
class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def read(self):
  n=int(self.headers.get('Content-Length','0')); return json.loads(self.rfile.read(n) or b'{}')
 def out(self,x,s=200): self._out=x; js(self,s)
 def req(self):
  p=self.path.split('?',1)[0]; return p
 def do_GET(self):
  p=self.req()
  if p=='/': return self.html()
  if p=='/api/health': return self.out({'status':'ok','node_id':NODE})
  u=auth(self.headers)
  if p=='/api/auth/me': return self.out({'user':user(u)} if u else {'error':'unauthorized'},200 if u else 401)
  if not u: return self.out({'error':'unauthorized'},401)
  c=conn()
  if p=='/api/workspaces':
   rows=c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall()
   return self.out({'workspaces':[dict(x) for x in rows]})
  m=re.match(r'/api/users/(\d+)$',p)
  if m:
   r=c.execute('SELECT * FROM users WHERE id=?',(m.group(1),)).fetchone(); return self.out({'user':user(r)} if r else {},200 if r else 404)
  m=re.match(r'/api/workspaces/([^/]+)$',p)
  if m:
   w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
   if not w:return self.out({},404)
   cs=c.execute('SELECT * FROM channels WHERE workspace_id=? AND (is_archived=0)',(w['id'],)).fetchall()
   return self.out({'workspace':dict(w),'channels':[dict(x) for x in cs],'read_state':{}})
  m=re.match(r'/api/workspaces/([^/]+)/members$',p)
  if m:
   w=c.execute('SELECT id FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
   rows=c.execute('SELECT m.*,u.username,u.display_name FROM members m JOIN users u ON u.id=m.user_id WHERE workspace_id=?',(w['id'],)).fetchall()
   return self.out({'members':[dict(x) for x in rows]})
  m=re.match(r'/api/channels/(\d+)/members$',p)
  if m:
   rows=c.execute('SELECT u.* FROM cmembers x JOIN users u ON u.id=x.user_id WHERE x.channel_id=?',(m.group(1),)).fetchall()
   return self.out({'members':[user(x) for x in rows]})
  m=re.match(r'/api/channels/(\d+)/messages$',p)
  if m:
   rows=c.execute('SELECT * FROM messages WHERE channel_id=? AND deleted=0 AND parent_id IS NULL ORDER BY id DESC LIMIT 200',(m.group(1),)).fetchall()
   return self.out({'messages':[msgobj(c,x) for x in rows],'next_cursor':None})
  m=re.match(r'/api/messages/(\d+)/replies$',p)
  if m:
   rows=c.execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(m.group(1),)).fetchall()
   return self.out({'replies':[msgobj(c,x) for x in rows],'next_cursor':None})
  m=re.match(r'/api/search$',p)
  if m:
   q=self.path.split('q=',1)[-1].split('&')[0]; rows=c.execute("SELECT * FROM messages WHERE body LIKE ? AND deleted=0 ORDER BY id DESC",(f'%{q}%',)).fetchall()
   return self.out({'results':[msgobj(c,x) for x in rows],'next_cursor':None})
  m=re.match(r'/api/channels/(\d+)/pins$',p)
  if m:
   rows=c.execute('SELECT p.*,m.* FROM pins p JOIN messages m ON m.id=p.message_id WHERE m.channel_id=?',(m.group(1),)).fetchall()
   return self.out({'pins':[{'message':msgobj(c,x),'pinned_by':x['user_id'],'pinned_at':x['pinned_at']} for x in rows],'next_cursor':None})
  c.close(); return self.out({},404)
 def do_POST(self):
  p=self.req(); b=self.read()
  if p=='/api/health': return self.out({'status':'ok','node_id':NODE})
  if p=='/api/auth/register':
   if not re.fullmatch(r'[A-Za-z0-9_]+',b.get('username','')) or len(b.get('password',''))<8:return self.out({},400)
   c=conn()
   try:
    c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(b['username'],hashlib.sha256(b['password'].encode()).hexdigest(),b.get('display_name',b['username']))); c.commit()
   except sqlite3.IntegrityError:return self.out({},409)
   r=c.execute('SELECT * FROM users WHERE username=?',(b['username'],)).fetchone(); t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,r['id'],)); c.commit(); return self.out({'user':user(r),'token':t},201)
  if p=='/api/auth/login':
   c=conn(); r=c.execute('SELECT * FROM users WHERE username=? AND password=?',(b.get('username'),hashlib.sha256(b.get('password','').encode()).hexdigest())).fetchone()
   if not r:return self.out({},401)
   t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,r['id'])); c.commit(); return self.out({'user':user(r),'token':t})
  u=auth(self.headers)
  if not u:return self.out({},401)
  c=conn()
  if p=='/api/workspaces':
   if not re.fullmatch(r'[a-z0-9-]{2,32}',b.get('slug','')):return self.out({},400)
   try:c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(b['slug'],b['name'],u['id'])); wid=c.lastrowid;c.execute('INSERT INTO members VALUES(?,?,?)',(wid,u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general')); cid=c.lastrowid;c.execute('INSERT INTO cmembers VALUES(?,?)',(cid,u['id']));c.commit()
   except sqlite3.IntegrityError:return self.out({},409)
   w=c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone();ch=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone();return self.out({'workspace':dict(w),'general_channel':dict(ch)},201)
  m=re.match(r'/api/workspaces/([^/]+)/channels$',p)
  if m:
   w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone(); role=c.execute('SELECT role FROM members WHERE workspace_id=? AND user_id=?',(w['id'],u['id'])).fetchone()
   if not role or (b.get('is_private') and role['role'] not in ('owner','admin')):return self.out({},403)
   if not re.fullmatch(r'[a-z0-9-]{1,32}',b.get('name','')):return self.out({},400)
   if c.execute('SELECT id FROM channels WHERE workspace_id=? AND name=?',(w['id'],b['name'])).fetchone():return self.out({},409)
   c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],b['name'],int(b.get('is_private',False)),b.get('topic','')));cid=c.lastrowid;c.execute('INSERT INTO cmembers VALUES(?,?)',(cid,u['id']));c.commit();return self.out({'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())},201)
  m=re.match(r'/api/channels/(\d+)/join$',p)
  if m:
   ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
   if not ch:return self.out({},404)
   c.execute('INSERT OR IGNORE INTO cmembers VALUES(?,?)',(ch['id'],u['id']));c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(ch['workspace_id'],u['id'],'member'));c.commit();return self.out({'channel':dict(ch)})
  m=re.match(r'/api/channels/(\d+)/messages$',p)
  if m:
   ch=c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone()
   if not ch:return self.out({},404)
   if not b.get('body','').strip():return self.out({},400)
   c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(ch['id'],u['id'],b['body'],b.get('parent_id'),now()));mid=c.lastrowid;r=c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone(); obj=msgobj(c,r); emit(c,ch['id'],'message.reply' if b.get('parent_id') else 'message.created',{'message':obj});return self.out({'message':obj},201)
  m=re.match(r'/api/messages/(\d+)/pin$',p)
  if m:
   c.execute('INSERT OR IGNORE INTO pins VALUES(?,?,?)',(m.group(1),u['id'],now()));c.commit();return self.out({'pin':{'message_id':int(m.group(1)),'pinned_by':u['id'],'pinned_at':now()}})
  m=re.match(r'/api/messages/(\d+)/reactions$',p)
  if m:
   c.execute('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(m.group(1),u['id'],b.get('emoji','👍')));c.commit();r=c.execute('SELECT emoji,COUNT(*) count FROM reactions WHERE message_id=? GROUP BY emoji',(m.group(1),)).fetchall();return self.out({'reactions':[dict(x) for x in r]})
  m=re.match(r'/api/invitations/([^/]+)/accept$',p)
  if m:
   x=c.execute('SELECT * FROM invites WHERE code=?',(m.group(1),)).fetchone()
   if not x or x['uses']>=x['max_uses']:return self.out({},404)
   c.execute('UPDATE invites SET uses=uses+1 WHERE code=?',(m.group(1),));c.execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(x['workspace_id'],u['id'],'member'));c.commit();return self.out({'accepted':True})
  return self.out({},404)
 def do_PATCH(self):
  p=self.req();b=self.read();u=auth(self.headers)
  if not u:return self.out({},401)
  c=conn()
  if p=='/api/users/me':
   fields={k:b[k] for k in ('display_name','timezone','avatar_url','status_text','status_emoji') if k in b}
   if fields:c.execute('UPDATE users SET '+','.join(k+'=?' for k in fields)+' WHERE id=?',list(fields.values())+[u['id']]);c.commit()
   return self.out({'user':user(c.execute('SELECT * FROM users WHERE id=?',(u['id'],)).fetchone())})
  m=re.match(r'/api/messages/(\d+)$',p)
  if m:
   r=c.execute('SELECT * FROM messages WHERE id=?',(m.group(1),)).fetchone()
   if not r or r['author_id']!=u['id']:return self.out({},403)
   c.execute('UPDATE messages SET body=?,edited_at=? WHERE id=?',(b.get('body',''),now(),m.group(1)));c.commit();return self.out({'message':msgobj(c,c.execute('SELECT * FROM messages WHERE id=?',(m.group(1),)).fetchone())})
  m=re.match(r'/api/channels/(\d+)$',p)
  if m:
   c.execute('UPDATE channels SET topic=? WHERE id=?',(b.get('topic',''),m.group(1)));c.commit();return self.out({'channel':dict(c.execute('SELECT * FROM channels WHERE id=?',(m.group(1),)).fetchone())})
  return self.out({},404)
 def do_DELETE(self):
  p=self.req();u=auth(self.headers)
  if not u:return self.out({},401)
  c=conn();m=re.match(r'/api/messages/(\d+)$',p)
  if m:c.execute('UPDATE messages SET deleted=1 WHERE id=?',(m.group(1),));c.commit();return self.out({'deleted':True})
  m=re.match(r'/api/messages/(\d+)/pin$',p)
  if m:c.execute('DELETE FROM pins WHERE message_id=?',(m.group(1),));c.commit();return self.out({'unpinned':True})
  return self.out({},404)
 def html(self):
  self.send_response(200);self.send_header('Content-Type','text/html');self.end_headers()
  self.wfile.write(b'''<!doctype html><html><head><title>Huddle</title><style>body{margin:0;font:14px Arial;display:flex;height:100vh}.side{width:240px;background:#3f0e40;color:white;padding:20px}.main{flex:1;padding:25px}.primary{background:#007a5a;color:#fff}.danger{background:#e01e5a;color:#fff}.secondary{background:#1264a3;color:#fff}button{padding:9px;border:0;margin:4px}input{padding:9px;margin:4px}</style></head><body><aside class=side><h2 data-testid=workspace-header>Huddle</h2><div data-testid=channel-list></div><button data-testid=new-channel-btn data-button-role=secondary>New channel</button></aside><main class=main><section data-testid=auth-modal><form data-testid=auth-form><input name=username placeholder=username><input name=password type=password placeholder=password><button data-testid=auth-submit data-button-role=primary>Sign in</button></form></section><h1 data-testid=channel-title># general</h1><div data-testid=message-list></div><input data-testid=message-input><button data-testid=send-btn data-button-role=primary>Send</button><button data-testid=logout-btn data-button-role=danger>Logout</button><div data-testid=thread-panel></div></main></body></html>''')
 def do_PUT(self): self.do_PATCH()
def run():
 init(); srv=ThreadingHTTPServer(('127.0.0.1',PORT),H); srv.serve_forever()
if __name__=='__main__':run()
PY
cat > /app/start.sh <<'SH'
#!/bin/sh
set -eu
mkdir -p /app
python3 /app/app.py >/tmp/huddle-8000.log 2>&1 & echo $! >/tmp/huddle-8000.pid
PORT=8001 python3 /app/app.py >/tmp/huddle-8001.log 2>&1 & echo $! >/tmp/huddle-8001.pid
PORT=8002 python3 /app/app.py >/tmp/huddle-8002.log 2>&1 & echo $! >/tmp/huddle-8002.pid
exec wait
SH
chmod +x /app/start.sh
cat > /app/requirements.txt <<'EOF'
EOF
ls -l /app/start.sh /app/app.py /app/requirements.txt
